const { searchTerm, filterProperty, filterOperator, filterValue, properties, limit } = $.input;
const body = { limit: Math.min(limit || 10, 100) };
body.properties = properties || ['email', 'firstname', 'lastname', 'phone', 'company', 'lifecyclestage'];
if (searchTerm) body.query = searchTerm;
if (filterProperty && filterValue) {
  body.filterGroups = [{
    filters: [{
      propertyName: filterProperty,
      operator: filterOperator || 'EQ',
      value: filterValue
    }]
  }];
}
return body;

const resp = $.steps.searchContacts.response || {};
const results = resp.results || [];
return {
  contacts: results.map(c => ({
    id: c.id,
    properties: c.properties || {},
    createdAt: c.createdAt,
    updatedAt: c.updatedAt
  })),
  total: resp.total || results.length,
  count: results.length,
  paging: resp.paging || null,
  summary: `Found ${resp.total || results.length} contact${(resp.total || results.length) === 1 ? '' : 's'}`
};
